export const PRIVACY_HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Mindrawer プライバシーポリシー / Privacy Policy</title>\n<style>\n:root { color-scheme: light dark; --bg: #f7f2ea; --fg: #2b2622; --muted: #6f6359; --accent: #c4552f; }\n@media (prefers-color-scheme: dark) { :root { --bg: #1d1a17; --fg: #ece5dc; --muted: #a89c90; --accent: #e7845f; } }\nbody { margin: 0; background: var(--bg); color: var(--fg); font: 16px/1.75 -apple-system, \"Hiragino Sans\", \"Noto Sans JP\", sans-serif; }\nmain { max-width: 720px; margin: 0 auto; padding: 32px 16px 64px; }\nh1 { font-size: 1.6rem; line-height: 1.3; } h2 { margin-top: 2.5rem; font-size: 1.3rem; border-bottom: 1px solid var(--muted); padding-bottom: .3rem; }\nh3 { font-size: 1.05rem; margin-top: 1.6rem; } a { color: var(--accent); overflow-wrap: anywhere; } p, li { color: var(--fg); } ul { padding-left: 1.3rem; }\n</style>\n</head>\n<body><main>\n<h1>プライバシーポリシー / Privacy Policy</h1>\n<p>最終更新日: 2026 年 10 月 20 日 / Last updated: October 20, 2026</p>\n<h2>日本語</h2>\n<p>Mindrawer（以下「本アプリ」）は、利用者のメモを利用者の端末の中に保存します。開発者が利用者の情報を集めることはありません。</p>\n<h3>保存する情報</h3>\n<ul>\n<li>利用者が保存したメモ、スクショ、設定は、利用者の iPhone の中（本アプリと共有シートの拡張機能が使う保存領域）にだけ保存されます。</li>\n<li>Anthropic の API キーは、利用者の端末のキーチェーンにだけ保存されます。</li>\n</ul>\n<h3>外部に送る情報</h3>\n<ul>\n<li>利用者が API キーを設定した場合に限り、メモの整理と取り出しのために、メモの本文・タイトル・タグなどと、添付したスクショを Anthropic, PBC の Claude API に送ります。送信には利用者自身の API キーを使います。送られた情報の扱いは Anthropic のプライバシーポリシーと商用利用規約に従います（<a href=\"https://www.anthropic.com/legal/privacy\">https://www.anthropic.com/legal/privacy</a>）。</li>\n<li>Mindrawer Plus（月額の購読）を利用している場合は、同じ内容を本アプリの中継サーバー（Cloudflare 上）を経由して Claude API に送ります。中継サーバーは購読の確認と月の利用回数・利用料金を数えるためだけに使い、メモの内容は保存しません。利用回数は App Store の購読番号（original transaction ID）ごとに数え、約 40 日で消えます。</li>\n<li>API キーも購読も使わない場合、本アプリは外部と通信しません。</li>\n</ul>\n<h3>集めない情報</h3>\n<ul>\n<li>開発者は、分析、広告、追跡のための情報を一切集めません。アカウント登録もありません。</li>\n</ul>\n<h3>許可を求める機能</h3>\n<ul>\n<li>マイクと音声認識: 声でメモを入力するときだけ使います。認識は Apple の音声認識機能で行われます。</li>\n<li>写真: 選んだスクショだけを読み込みます。</li>\n<li>通知: リマインド日の通知を端末の中で予約するために使います。</li>\n</ul>\n<h3>データの削除</h3>\n<ul>\n<li>アプリ内でメモを削除するか、本アプリを削除すると、端末内のデータは消えます。</li>\n</ul>\n<h3>お問い合わせ</h3>\n<p>GitHub の Issues（<a href=\"https://github.com/Yusuke827827/hikidashi/issues\">https://github.com/Yusuke827827/hikidashi/issues</a>）からご連絡ください。</p>\n<h2>English</h2>\n<p>Mindrawer (&quot;the app&quot;) keeps your notes on your device. The developer does not collect any of your information.</p>\n<h3>What is stored</h3>\n<ul>\n<li>Notes, screenshots and settings you save stay on your iPhone, in storage shared only by the app and its share extension.</li>\n<li>Your Anthropic API key is stored only in your device's keychain.</li>\n</ul>\n<h3>What is sent</h3>\n<ul>\n<li>Only if you set an API key, the app sends note text, titles, tags and attached screenshots to Anthropic, PBC's Claude API to file and recall your notes, using your own key. Anthropic handles that data under its privacy policy and commercial terms (<a href=\"https://www.anthropic.com/legal/privacy\">https://www.anthropic.com/legal/privacy</a>).</li>\n<li>If you subscribe to Mindrawer Plus, the same content is sent to the Claude API through the app's relay server (on Cloudflare). The relay only checks your subscription and counts monthly usage and cost; it does not store your notes. Usage is counted per App Store original transaction ID and expires after about 40 days.</li>\n<li>Without an API key or a subscription, the app does not connect to any server.</li>\n</ul>\n<h3>What is not collected</h3>\n<ul>\n<li>The developer collects no analytics, advertising or tracking data. There are no accounts.</li>\n</ul>\n<h3>Permissions</h3>\n<ul>\n<li>Microphone and speech recognition: used only while you dictate a note, through Apple's speech recognition.</li>\n<li>Photos: only the screenshot you pick is read.</li>\n<li>Notifications: used to schedule reminder notifications on the device.</li>\n</ul>\n<h3>Deleting data</h3>\n<ul>\n<li>Deleting a note in the app, or deleting the app, removes the data from your device.</li>\n</ul>\n<h3>Contact</h3>\n<p>Please open an issue at <a href=\"https://github.com/Yusuke827827/hikidashi/issues.\">https://github.com/Yusuke827827/hikidashi/issues.</a></p>\n</main></body>\n</html>\n";

export const SUPPORT_HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Mindrawer サポート / Support</title>\n<style>\n:root { color-scheme: light dark; --bg: #f7f2ea; --fg: #2b2622; --muted: #6f6359; --accent: #c4552f; }\n@media (prefers-color-scheme: dark) { :root { --bg: #1d1a17; --fg: #ece5dc; --muted: #a89c90; --accent: #e7845f; } }\nbody { margin: 0; background: var(--bg); color: var(--fg); font: 16px/1.75 -apple-system, \"Hiragino Sans\", \"Noto Sans JP\", sans-serif; }\nmain { max-width: 720px; margin: 0 auto; padding: 32px 16px 64px; }\nh1 { font-size: 1.6rem; line-height: 1.3; } h2 { margin-top: 2.5rem; font-size: 1.3rem; border-bottom: 1px solid var(--muted); padding-bottom: .3rem; }\nh3 { font-size: 1.05rem; margin-top: 1.6rem; } a { color: var(--accent); overflow-wrap: anywhere; } p, li { color: var(--fg); } ul { padding-left: 1.3rem; }\n</style>\n</head>\n<body><main>\n<h1>Mindrawer サポート / Support</h1>\n<h2>日本語</h2>\n<p>Mindrawer は、X や日々の暮らしで見つけた Tips や備忘録をしまっておき、必要なときに取り出すためのメモアプリです。</p>\n<h3>よくある質問</h3>\n<p><strong>共有シートに Mindrawer が出てきません</strong></p>\n<p>共有シートのアプリの列を右端までスクロールし、「その他」から Mindrawer をオンにしてください。</p>\n<p><strong>Mindrawer Plus を解約したい</strong></p>\n<p>iPhone の「設定」→ 自分の名前 →「サブスクリプション」→ Mindrawer Plus から解約できます。期間の終わりまでは使えます。</p>\n<p><strong>機種変更したら Plus が使えなくなりました</strong></p>\n<p>アプリの「設定」→ Mindrawer Plus →「購入を復元」を押してください。</p>\n<p><strong>「今月の AI の利用上限に達しました」と出ます</strong></p>\n<p>1 人あたり月の利用に上限があります。翌月になるとまた使えます。自分の Anthropic API キーを設定すれば、すぐに使えます。</p>\n<p><strong>メモを別の端末に移したい</strong></p>\n<p>「設定」→「データ」→「書き出す（JSON）」で書き出し、新しい端末で「読み込む（JSON）」を使ってください。</p>\n<h3>お問い合わせ</h3>\n<p>GitHub の Issues（<a href=\"https://github.com/Yusuke827827/hikidashi/issues\">https://github.com/Yusuke827827/hikidashi/issues</a>）からご連絡ください。</p>\n<h2>English</h2>\n<p>Mindrawer keeps the tips and notes you pick up every day and hands them back when you need them.</p>\n<h3>FAQ</h3>\n<p><strong>Mindrawer isn't in the share sheet</strong></p>\n<p>Scroll the app row in the share sheet to the end, tap More, and turn on Mindrawer.</p>\n<p><strong>How do I cancel Mindrawer Plus?</strong></p>\n<p>Open Settings on your iPhone → your name → Subscriptions → Mindrawer Plus. You keep access until the end of the period.</p>\n<p><strong>Plus stopped working on my new phone</strong></p>\n<p>In the app, open Settings → Mindrawer Plus → Restore purchases.</p>\n<p><strong>&quot;You've reached this month's AI limit&quot;</strong></p>\n<p>Each subscriber has a monthly limit. It resets next month, or add your own Anthropic API key to keep going.</p>\n<p><strong>Moving notes to another device</strong></p>\n<p>Use Settings → Data → Export (JSON), then Import (JSON) on the new device.</p>\n<h3>Contact</h3>\n<p>Please open an issue at <a href=\"https://github.com/Yusuke827827/hikidashi/issues.\">https://github.com/Yusuke827827/hikidashi/issues.</a></p>\n</main></body>\n</html>\n";
